import{_ as e,o as l,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"단축키 및 인터랙션 제스처","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/hotkeys.md","filePath":"ko-KR/user-guide/hotkeys.md","lastUpdated":1788171291000}'),r={name:"ko-KR/user-guide/hotkeys.md"};function a(n,t,s,i,g,c){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="단축키-및-인터랙션-제스처" tabindex="-1">단축키 및 인터랙션 제스처 <a class="header-anchor" href="#단축키-및-인터랙션-제스처" aria-label="Permalink to &quot;단축키 및 인터랙션 제스처&quot;">​</a></h1><p>Lertaro는 키보드 우선 인터랙션 설계를 채택하면서도, 풍부한 마우스 제스처와 다단계 퀵 내비게이션을 제공합니다. 고정 키를 제외한 모든 전역 및 앱 내부 단축키는 <a href="./settings/hotkeys-page.html"><strong>설정 → 단축키</strong></a>에서 자유롭게 변경할 수 있습니다.</p><h2 id="_1-전역-단축키-요약표" tabindex="-1">1. 전역 단축키 요약표 <a class="header-anchor" href="#_1-전역-단축키-요약표" aria-label="Permalink to &quot;1. 전역 단축키 요약표&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">기능/액션</th><th style="text-align:left;">기본 단축키</th><th style="text-align:left;">기능 설명 및 상세 인터랙션</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>퀵 윈도우 표시/숨기기</strong></td><td style="text-align:left;"><code>Ctrl</code> 더블 클릭</td><td style="text-align:left;">더블 클릭 방식 또는 일반 조합키(예: <code>Alt+Space</code>, <code>Win+Space</code>)로 변경할 수 있습니다. <strong>전체 패널을 기본으로 열기</strong>를 켜면 이 단축키가 메인 윈도우를 엽니다. 처음 표시될 때는 한 번만 전경 및 포커스를 처리하고, 표시되어 있지만 비활성 상태이면 다시 활성화하며, 이미 활성 상태이면 다시 누를 때 닫습니다. 자동으로 항상 위에 유지하지는 않습니다.</td></tr><tr><td style="text-align:left;"><strong>퀵 점프 (Quick Jump)</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">파일 대화상자 내에서 최근 탐색기나 퀵 패널에서 열람했던 폴더로 즉시 이동.</td></tr><tr><td style="text-align:left;"><strong>다음 항목 선택</strong></td><td style="text-align:left;"><code>Ctrl+N</code> 또는 <code>↓</code></td><td style="text-align:left;">목록에서 강조 표시를 아래로 이동. 퀵 패널에서는 그룹을 건너뛰며 연속 탐색할 수 있습니다. 퀵 런치 패널이 표시되고 검색어가 비어 있으면 <code>Ctrl+N</code>으로 다음 소스를 순환하며 마지막 다음에는 처음으로 돌아갑니다.</td></tr><tr><td style="text-align:left;"><strong>이전 항목 선택</strong></td><td style="text-align:left;"><code>Ctrl+P</code> 또는 <code>↑</code></td><td style="text-align:left;">목록에서 강조 표시를 위로 이동. 퀵 패널에서도 그룹 간 이동을 지원합니다. 퀵 런치 패널이 표시되고 검색어가 비어 있으면 <code>Ctrl+P</code>로 이전 소스를 순환하며 처음 이전에는 마지막으로 돌아갑니다.</td></tr><tr><td style="text-align:left;"><strong>1~9번 결과로 즉시 이동</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">조합키 변경 가능. 퀵 윈도우 결과 옆에 번호 배지가 표시되어 즉시 실행 가능.</td></tr><tr><td style="text-align:left;"><strong>액션 메뉴 열기</strong></td><td style="text-align:left;"><code>Ctrl+O</code> 또는 <code>→</code></td><td style="text-align:left;">선택 항목의 컨텍스트 액션 패널 확장(경로 복사, 속성, 관리자 실행, 파일 조작 등).</td></tr><tr><td style="text-align:left;"><strong>선택 항목으로 검색어 자동완성</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">현재 선택된 항목의 이름 또는 전체 경로를 검색창에 채워 2차 필터링 수행.</td></tr><tr><td style="text-align:left;"><strong>QuickLook 즉시 미리보기</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">사이드 미리보기 패널 열기/닫기(이미지, 문서, 오디오/비디오 즉시 재생, 폴더 구조).</td></tr><tr><td style="text-align:left;"><strong>이전 검색 기록어</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">최근 입력했던 검색 키워드를 뒤로 탐색.</td></tr><tr><td style="text-align:left;"><strong>다음 검색 기록어</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">최근 입력했던 검색 키워드를 앞으로 탐색.</td></tr><tr><td style="text-align:left;"><strong>현재 검색 기록어 삭제</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">현재 표시된 검색 키워드를 기록에서 제거.</td></tr><tr><td style="text-align:left;"><strong>메인 윈도우 열기</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">현재 입력 중인 검색어를 유지한 채 대형 메인 검색창 열기.</td></tr><tr><td style="text-align:left;"><strong>LocalSend 전송창 열기</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">LocalSend 무선 LAN 전송창을 열어 다른 기기로 파일이나 텍스트를 빠르게 전송.</td></tr><tr><td style="text-align:left;"><strong>창 고정 (항상 유지)</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">포커스를 잃어도 창이 닫히지 않도록 고정(다른 창에서 텍스트를 복사해 올 때 유용).</td></tr><tr><td style="text-align:left;"><strong>퀵 패널 표시/숨기기</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">현재 활성 창 옆에 최근 파일, 즐겨찾기, 워크스페이스가 포함된 패널 도킹.</td></tr></tbody></table><h2 id="_2-검색창-아이콘-및-마우스-제스처" tabindex="-1">2. 검색창 아이콘 및 마우스 제스처 <a class="header-anchor" href="#_2-검색창-아이콘-및-마우스-제스처" aria-label="Permalink to &quot;2. 검색창 아이콘 및 마우스 제스처&quot;">​</a></h2><p>검색창 내부의 작은 로고 아이콘은 브랜드 표시뿐 아니라 실용적인 마우스 제스처를 제공합니다.</p><h3 id="퀵-윈도우-로고-제스처" tabindex="-1">퀵 윈도우 로고 제스처 <a class="header-anchor" href="#퀵-윈도우-로고-제스처" aria-label="Permalink to &quot;퀵 윈도우 로고 제스처&quot;">​</a></h3><ul><li><strong>좌클릭</strong>: 커서 위치에 메인 팝업 메뉴 표시(메인 창 표시, 단축키 전환, 설정, 정보, 클린 종료, 종료). &quot;메인 창 표시&quot;는 현재 검색어를 유지합니다.</li><li><strong>좌클릭 드래그</strong>: 검색바 위치를 자유롭게 이동. <strong><code>Ctrl</code> 키를 누른 채 드래그</strong>하면 이동 방향이 <strong>수직 방향으로 고정</strong>되어 수평 위치가 틀어지지 않습니다.</li><li><strong>우클릭</strong>: 설정된 창 크기를 유지한 채 퀵 윈도우를 화면 중앙 기본 위치로 즉시 리셋.</li><li><strong>휠클릭 (중간 버튼)</strong>: 창 &quot;고정&quot; 상태를 토글. 고정 중에는 로고가 밝게 점등됩니다.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>퀵 윈도우가 기억하는 좌표는 해당 모니터에 대한 <strong>상대 비율 좌표</strong>입니다. 해상도나 DPI 배율이 다른 모니터로 이동하더라도 화면 밖으로 벗어나지 않도록 자동 계산됩니다.</p></div><h3 id="인라인-및-메인-윈도우-로고" tabindex="-1">인라인 및 메인 윈도우 로고 <a class="header-anchor" href="#인라인-및-메인-윈도우-로고" aria-label="Permalink to &quot;인라인 및 메인 윈도우 로고&quot;">​</a></h3><ul><li><strong>인라인 윈도우</strong>: 네이티브 파일 대화상자(열기/저장/찾아보기)에 임베드된 경우, 로고를 좌클릭하여 <a href="#3-퀵-내비게이션-마우스-트리거"><strong>퀵 내비게이션</strong></a> 계단식 메뉴를 표시합니다.</li><li><strong>메인 윈도우</strong>: 로고를 좌클릭하면 컨텍스트 메뉴가 열립니다. 이미 메인 윈도우가 열려 있으므로 메뉴에서 <strong>메인 창 표시</strong> 항목은 숨겨집니다. 가운데 버튼을 클릭하면 창 고정 상태를 전환합니다.</li></ul><h2 id="_3-퀵-내비게이션-마우스-트리거" tabindex="-1">3. 퀵 내비게이션 (마우스 트리거) <a class="header-anchor" href="#_3-퀵-내비게이션-마우스-트리거" aria-label="Permalink to &quot;3. 퀵 내비게이션 (마우스 트리거)&quot;">​</a></h2><p>타이핑 없이 마우스 클릭만으로 자주 쓰는 디렉토리에 바로 이동하거나 파일을 열 수 있습니다.</p><h3 id="트리거-환경" tabindex="-1">트리거 환경 <a class="header-anchor" href="#트리거-환경" aria-label="Permalink to &quot;트리거 환경&quot;">​</a></h3><ul><li><strong>바탕화면 빈 공간</strong>: 휠클릭(또는 좌클릭 더블클릭)하여 메뉴 열기. 폴더나 파일을 클릭하여 즉시 실행.</li><li><strong>파일 탐색기</strong>: 탐색기 빈 공간을 휠클릭하여 열기. 클릭한 폴더로 현재 탐색기가 즉시 이동.</li><li><strong>지원 파일 관리자</strong>: Directory Opus, Total Commander, XYplorer, Files, One Commander 등의 목록 영역을 휠클릭(<a href="./file-manager-support.html"><strong>지원 파일 관리자</strong></a> 참고).</li><li><strong>파일 대화상자</strong>: 열기/저장 대화상자에서 휠클릭 또는 로고 클릭하여 대상 폴더로 안전하게 이동.</li></ul><h3 id="계단식-메뉴-구성-및-관리" tabindex="-1">계단식 메뉴 구성 및 관리 <a class="header-anchor" href="#계단식-메뉴-구성-및-관리" aria-label="Permalink to &quot;계단식 메뉴 구성 및 관리&quot;">​</a></h3><p><strong>Folder Cascader</strong> 플러그인을 통해 구동됩니다.</p><ol><li><strong>현재 열린 폴더</strong>: 지원되는 모든 파일 관리자에서 현재 열려 있는 폴더를 자동 집계 및 중복 제거하여 표시.</li><li><strong>즐겨찾기 및 기록</strong>: 별표 표시된 즐겨찾기와 최근 접근 기록 목록.</li><li><strong>사용자 지정 분류</strong>: <strong>설정 → 플러그인 → Folder Cascader</strong>에서 다단계 서브메뉴 구성 가능(예: <code>업무/프로젝트A</code>).</li><li><strong>빠른 폴더 추가 (<code>+</code> 버튼)</strong>: 메뉴 각 계층의 헤더에 있는 <code>+</code> 버튼을 클릭하여 현재 열린 폴더를 해당 분류에 즉시 저장.</li></ol><h2 id="_4-변경-불가능한-핵심-고정-키" tabindex="-1">4. 변경 불가능한 핵심 고정 키 <a class="header-anchor" href="#_4-변경-불가능한-핵심-고정-키" aria-label="Permalink to &quot;4. 변경 불가능한 핵심 고정 키&quot;">​</a></h2><p>일관된 조작성을 보장하기 위해 다음 키는 항상 고정 동작합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">키</th><th style="text-align:left;">상황</th><th style="text-align:left;">동작</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">결과 목록</td><td style="text-align:left;">선택한 항목(파일/폴더/앱/액션)을 엽니다.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">결과 목록</td><td style="text-align:left;">파일 탐색기에서 해당 파일의 위치를 열고 선택합니다.</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">결과 목록</td><td style="text-align:left;">관리자 권한으로 실행합니다.</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">모든 상황</td><td style="text-align:left;">검색어가 있으면 지우고, 비어 있으면 창을 닫거나 메뉴를 종료합니다.</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">액션 메뉴</td><td style="text-align:left;">필터 검색어가 빈 상태에서 누르면 액션 메뉴를 닫고 검색 목록으로 돌아갑니다.</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> 방향키</td><td style="text-align:left;">액션 메뉴</td><td style="text-align:left;">왼쪽 키는 상위 메뉴로, 오른쪽 키는 하위 메뉴로 진입합니다.</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">Lertaro의 모든 창</td><td style="text-align:left;">오작동 방지를 위해 시스템 타이틀바 메뉴를 차단합니다.</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">메인 / 설정 창</td><td style="text-align:left;">창을 닫습니다. 퀵 윈도우, 인라인, 미리보기 창에서는 차단됩니다.</td></tr></tbody></table><h2 id="_5-플러그인-액션-단축키-및-프로세스-블랙리스트" tabindex="-1">5. 플러그인 액션 단축키 및 프로세스 블랙리스트 <a class="header-anchor" href="#_5-플러그인-액션-단축키-및-프로세스-블랙리스트" aria-label="Permalink to &quot;5. 플러그인 액션 단축키 및 프로세스 블랙리스트&quot;">​</a></h2><h3 id="플러그인-액션-단축키" tabindex="-1">플러그인 액션 단축키 <a class="header-anchor" href="#플러그인-액션-단축키" aria-label="Permalink to &quot;플러그인 액션 단축키&quot;">​</a></h3><p>플러그인은 고유 액션 단축키를 등록할 수 있습니다(예: 경로 복사 <code>Ctrl+Shift+C</code>, 파일 잘라내기 <code>Ctrl+X</code>, 복사 <code>Ctrl+C</code>, 붙여넣기 <code>Ctrl+V</code>, 삭제 <code>Delete</code>, 영구 삭제 <code>Shift+Delete</code> 등). <strong>설정 → 단축키 → 플러그인 액션</strong>에서 관리할 수 있습니다.</p><h3 id="프로세스-블랙리스트-및-전체화면-자동-무시" tabindex="-1">프로세스 블랙리스트 및 전체화면 자동 무시 <a class="header-anchor" href="#프로세스-블랙리스트-및-전체화면-자동-무시" aria-label="Permalink to &quot;프로세스 블랙리스트 및 전체화면 자동 무시&quot;">​</a></h3><ul><li><strong>전체화면 앱 자동 무시</strong>: 전체화면 3D 게임이나 비디오 플레이어가 감지되면 Lertaro는 전역 단축키를 자동으로 통과시켜 게임 조작을 방해하지 않습니다.</li><li><strong>사용자 지정 프로세스 블랙리스트</strong>: <a href="./settings/hotkeys-page.html#프로세스-블랙리스트"><strong>설정 → 단축키</strong></a>에 특정 프로세스(예: <code>game.exe</code>)를 등록하면 해당 앱 활성 시 단축키가 무음 처리됩니다.</li></ul>',26)])])}const x=e(r,[["render",a]]);export{h as __pageData,x as default};
